fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    // Compute the effective rotation, modulo the length.
    let k = n % len;
    // verifier often needs to know k < len
    assert!(k < len);
    // s is the split point: len - k
    let s = len - k;
    // verifier often needs to know s <= len
    assert!(s <= len);

    // Allocate a new Vec with the same capacity as the input
    let mut rotated = Vec::with_capacity(len);

    // Push the suffix from s..len
    rotated.extend_from_slice(&list[s..]);
    // Push the prefix from 0..s
    rotated.extend_from_slice(&list[..s]);

    rotated
}

